head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 초기화함수
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92015.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {

    scwin.param = $c.data.getParameter();

    // 엔터키 조회 세팅
    $c.win.setEnterKeyEvent(grp_search, scwin.btn_search_onclick);
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/// EVENT ///

/**
 * @method
 * @name rd_searchType_onviewchange
 * @description 검색조건 변경
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_searchType_onviewchange = function (info) {
    try {
        const type = info.value;

        scwin.searchResult(false); // 검색 초기화
        dma_Req.setEmptyValue(); // 입력 초기화
        dma_Req.set("searchType", type);

        if(type === "1") {
            // 검색조건
            grp_search1.show("");
            grp_search2.hide("");
            grp_search3_1.hide("");
            grp_search3_2.hide("");

            // 안내문구
            grp_info1.show("");
            grp_info2.hide("");
            grp_info3.hide("");

            // 조회버튼
            btn_search.show("");
        } else if(type === "2") {
            // 검색조건
            grp_search1.hide("");
            grp_search2.show("");
            grp_search3_1.hide("");
            grp_search3_2.hide("");

            // 안내문구
            grp_info1.hide("");
            grp_info2.show("");
            grp_info3.hide("");

            // 조회버튼
            btn_search.show("");

        } else if(type === "3") {
            // 검색조건
            grp_search1.hide("");
            grp_search2.hide("");
            grp_search3_1.show("");
            grp_search3_2.show("");

            // 안내문구
            grp_info1.hide("");
            grp_info2.hide("");
            grp_info3.show("");

            // 조회버튼
            btn_search.hide("");
        }

    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92015.rd_searchType_onviewchange" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 조회 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_search_onclick = async function (e) {
    try {
        let type = rd_searchType.getValue();
        if(await scwin.checkValues(type)) {
            scwin.sbmSelectRoadZip();

        } else {
            if(type === "1") {
                ipt_raodNm1.focus();
            } else if(type === "2") {
                ipt_bldgNo.focus();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92015.btn_search_onclick" });
    }
};

/**
 * @method
 * @name btn_confirm_onclick
 * @description 직접입력 확인 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_confirm_onclick = async function (e) {
    try {
        await scwin.otherZipCodeChk();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF92015.btn_confirm_onclick" });
    }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description 닫기 버튼 클릭
 * @returns {void}
 * @hidden N
 */
scwin.btn_cancel_onclick = function () {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92015.btn_cancel_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_oncellclick
 * @description row 선택
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_oncellclick = function (rowIndex, columnIndex, columnId) {
    try {
        let rowData = dlt_AddrListRes.getRowJSON(rowIndex);
        if(rowData && rowData.zipCd && rowData.roadAddr) {
            scwin.setZipCodePop(rowData.zipCd, rowData.roadAddr);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF92015.grd_Grid_oncellclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/// SUBMISSION ///

/**
 * @method
 * @name sbmSelectRoadZip
 * @description 우편번호 조회 요청
 * @returns {void}
 * @hidden N
 */
scwin.sbmSelectRoadZip = function () {
    const id = "sbm_SelectRoadZip";
    const sbmOptions = {
        id : id,
        method: "get",
        action : "/api/listing/common/pop/etc/zipcd/select-list",
        ref : "dma_Req",
        target : "dlt_AddrListRes=body",
        gridview : "grd_Grid|nofocus",
        submitDoneHandler : "scwin."+id+"_submitdone",
        isProcessMsg : false
    };
    $c.sbm.executeDynamic(sbmOptions);

};

/**
 * @method
 * @name sbm_SelectRoadZip_submitdone
 * @description 우편번호 조회 요청 성공
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbm_SelectRoadZip_submitdone = function (e) {
    const res = e.responseJSON;
    if(res.body && res.body.length > 0) {
        scwin.searchResult(true);
        scwin.fmtAddr(res.body);

    } else {
        scwin.searchResult(false);
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/// FUNCTION ///

/**
 * @method
 * @name fmtAddr
 * @description row에 표시되는 주소 컬럼 포맷
 * @param {*} resList resList
 * @returns {void}
 * @hidden N
 */
scwin.fmtAddr = function (resList) {
    dlt_AddrListRes.setBroadcast(false);
    for (let i = 0; i < resList.length; i++) {
        const item = resList[i];
        let addr = "<span class='txt_blue'>"+item.roadAddr+"</span>";
        addr += "</br>";
        addr += "<span style='padding: 0 4px;'> "+item.jibunAddr+"</span>";

        dlt_AddrListRes.setCellData(i, "displayAddr", addr);
    }
    dlt_AddrListRes.setBroadcast(true, true);
};

/**
 * @method
 * @name searchResult
 * @description 검색결과 표시
 * @param {*} isResult isResult
 * @returns {void}
 * @hidden N
 */
scwin.searchResult = function (isResult) {
    if(isResult) {
        grp_zipLoad.show("");
        grp_resMsgBox.hide("");

    } else {
        txt_message.setValue("조회 내역이 없습니다.");
        grp_zipLoad.hide("");
        grp_resMsgBox.show("");
    }
};

/**
 * @method
 * @name checkValues
 * @description 조회 필수값 검증
 * @param {*} type type
 * @returns {Boolean}
 * @hidden N
 */
scwin.checkValues = async function (type) {
    if(type === "1") { // 도로명 검색
        let roadNm = ipt_raodNm1.getValue();
        let bldgNo = ipt_bldgNo.getValue();
        if(!roadNm) {
            await $c.win.alert("검색할 도로명을 입력해 주세요.", () => {ipt_raodNm1.focus();});
            return false;
        } else if(roadNm.length < 2) {
            await $c.win.alert("도로명은 두글자 이상 입력되어야 합니다.", () => {ipt_raodNm1.focus();});
            return false;
        } else if(scwin.specialWord(roadNm) || scwin.specialWord(bldgNo)) {
            await $c.win.alert("%는 사용 할 수 없습니다.", () => {ipt_raodNm1.focus();});
            return false;
        } else {
            return true;
        }

    } else if(type === "2") { // 건물명 검색
        let roadNm = ipt_raodNm2.getValue();
        let bldgNm = ipt_bldgNm.getValue();
        if(!bldgNm) {
            await $c.win.alert("검색할 건물명을 입력해 주세요.", () => {ipt_bldgNm.focus();});
            return false;
        } else if(bldgNm.length < 2) {
            await $c.win.alert("건물명은 두글자 이상 입력되어야 합니다.", () => {ipt_bldgNm.focus();});
            return false;
        } else if(scwin.specialWord(bldgNm)) {
            await $c.win.alert("%는 사용 할 수 없습니다.", () => {ipt_bldgNm.focus();});
            return false;
        } else if(scwin.specialWord(roadNm)) {
            await $c.win.alert("%는 사용 할 수 없습니다.", () => {ipt_raodNm2.focus();});
            return false;
        } else {
            return true;
        }

    } else {
        await $c.win.alert("검색조건을 선택하세요.");
        return false;
    }
};

/**
 * @method
 * @name specialWord
 * @description 검색어에 특수문자(%) 포함 여부
 * @param {String} str str
 * @returns {Boolean}
 * @hidden N
 */
scwin.specialWord = function (str) {
    let reg = /%/;
    if (str === null || str === ""){
        return false;
    }
    if(reg.test(str)){
        return true;
    }
};

/**
 * @method
 * @name otherZipCodeChk
 * @description 직접입력 입력값 검증
 * @returns {void}
 * @hidden N
 */
scwin.otherZipCodeChk = async function () {
    let zipNo = ipt_zipCode.getValue();
    let addr = ipt_addr.getValue();
    if(!zipNo) {
        await $c.win.alert("우편번호를 입력해 주세요.", () => {ipt_zipCode.focus();});
        return;
    }

    if(/[^0123456789]/g.test(zipNo)) {

        if(zipNo !== "-") {
            await $c.win.alert("우편번호는 숫자 또는 -만 가능합니다.", () => {ipt_zipCode.focus();});
            return;
        }
    }

    if(!addr) {
        await $c.win.alert("주소를 입력해 주세요.", () => {ipt_addr.focus();});
        return;
    }

    scwin.setZipCodePop(zipNo, addr);
};

/**
 * @method
 * @name setZipCodePop
 * @description 선택한 우편번호·주소를 오프너 콜백으로 전달하고 팝업을 닫는다
 * @param {*} zipNo zipNo
 * @param {*} addr addr
 * @returns {void}
 * @hidden N
 */
scwin.setZipCodePop = function (zipNo, addr) {
    $c.win.closePopup({"zipNo":zipNo, "addr":addr, "req": scwin.param.data}, scwin.param.callbackFn);
};
